@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @bind:get="_query"
           @bind:set="OnQueryChanged"
           @bind:event="oninput" />

    @if (_loading)
    {
        <div class="product-search-status">Searching…</div>
    }
    else if (_error is not null)
    {
        <div class="product-search-error">
            <span>Search failed: @_error</span>
            <button @onclick="RetrySearch">Retry</button>
        </div>
    }
    else if (_hasSearched && _results.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_results.Count > 0)
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" loading="lazy" />
                    <h3>@product.Name</h3>
                    <p class="product-price">@product.Price.ToString("C")</p>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _query = string.Empty;
    private List<Product> _results = new();
    private bool _loading;
    private bool _hasSearched;
    private string? _error;

    private CancellationTokenSource? _debounceCts;
    private CancellationTokenSource? _searchCts;
    private Timer? _debounceTimer;

    private async Task OnQueryChanged(string value)
    {
        _query = value;

        // Cancel any pending debounce and in-flight search.
        CancelPending();

        if (string.IsNullOrWhiteSpace(value))
        {
            _results = new();
            _hasSearched = false;
            _error = null;
            return;
        }

        _debounceCts = new CancellationTokenSource();
        var token = _debounceCts.Token;

        // Wait 300ms (debounce). If the user types again, the token is
        // cancelled before the timer fires, so no search runs.
        var tcs = new TaskCompletionSource();
        _debounceTimer = new Timer(_ => tcs.TrySetResult(), null, 300, Timeout.Infinite);

        try
        {
            await using (token.Register(() => tcs.TrySetCanceled(token)))
            {
                await tcs.Task;
            }
        }
        catch (OperationCanceledException)
        {
            return;
        }

        await ExecuteSearch(value);
    }

    private async Task ExecuteSearch(string query)
    {
        _searchCts = new CancellationTokenSource();
        var token = _searchCts.Token;

        _loading = true;
        _error = null;

        try
        {
            var results = await ProductService.SearchAsync(query, token);

            token.ThrowIfCancellationRequested();

            _results = results;
            _hasSearched = true;
        }
        catch (OperationCanceledException)
        {
            // Search was superseded by a newer query; do nothing.
        }
        catch (Exception ex)
        {
            if (!token.IsCancellationRequested)
            {
                _error = ex.Message;
                _results = new();
                _hasSearched = true;
            }
        }
        finally
        {
            if (!token.IsCancellationRequested)
            {
                _loading = false;
            }
        }
    }

    private async Task RetrySearch()
    {
        if (!string.IsNullOrWhiteSpace(_query))
        {
            await ExecuteSearch(_query);
        }
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private void CancelPending()
    {
        _debounceTimer?.Dispose();
        _debounceTimer = null;

        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
        _debounceCts = null;

        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

